--

ALTER TABLE ONLY public.minigame_sessions
    ADD CONSTRAINT minigame_sessions_winner_id_fkey FOREIGN KEY (winner_id) REFERENCES public.users(id);


--

-- Name: create_minigame_session(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_minigame_session(p_group_id uuid, p_game_type text, p_wager integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_session_id uuid;
    v_game_type public.mini_game_type;
    v_current_user uuid;
BEGIN
    -- 1. Authentication gate. auth.uid() resolves in the auth schema by
    --    explicit qualification; anon callers (auth.uid() = NULL) fail here.
    v_current_user := auth.uid();
    IF v_current_user IS NULL THEN
        RETURN jsonb_build_object('status', 'not_authenticated');
    END IF;

    -- 2. Group-membership gate (direct-minigames 2026-08-27): a NULL
    --    p_group_id = DIRECT session and needs no group; a non-null group
    --    still requires active membership. Never trusting the client — the
    --    membership check stays server-side via is_group_member.
    IF p_group_id IS NOT NULL AND NOT public.is_group_member(p_group_id) THEN
        RETURN jsonb_build_object('status', 'not_member');
    END IF;

    -- 3. Wager validation (GMCR: integer shards >= 0; 0 = no wager).
    IF p_wager < 0 THEN
        RETURN jsonb_build_object('status', 'invalid_wager');
    END IF;

    -- 4. Game-type validation against the mini_game_type enum (the cast
    --    raises invalid_text_representation for unknown values).
    BEGIN
        v_game_type := p_game_type::public.mini_game_type;
    EXCEPTION WHEN invalid_text_representation THEN
        RETURN jsonb_build_object('status', 'invalid_game_type');
    END;

    -- 5. Wager escrow — deduct immediately (GWAG: "deducted immediately on
    --    acceptance and held in escrow"; the deduction IS the loss record).
    --    The guarded UPDATE never overdraws; SECURITY DEFINER bypasses the
    --    G-03 column REVOKE + assert_safe_user_update privileged gate.
    IF p_wager > 0 THEN
        UPDATE public.users
        SET personal_shards = personal_shards - p_wager
        WHERE id = v_current_user AND personal_shards >= p_wager;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('status', 'insufficient_shards');
        END IF;
    END IF;

    -- 6. Session insert (GMCR step 4: status=active; the initiator is the
    --    first participant — the participant-select UI is future work).
    INSERT INTO public.minigame_sessions
        (group_id, game_type, status, shard_wager, participants)
    VALUES
        (p_group_id, v_game_type, 'active', p_wager, ARRAY[v_current_user])
    RETURNING id INTO v_session_id;

    -- 7. Ledger entry with the session reference (escrow verifiability:
    --    sum of minigame_wager rows for this session = pot).
    IF p_wager > 0 THEN
        INSERT INTO public.shard_ledger (user_id, delta, reason, reference_id)
        VALUES (v_current_user, -p_wager, 'minigame_wager', v_session_id);
    END IF;

    RETURN jsonb_build_object('status', 'created', 'sessionId', v_session_id);
END;
$$;


--

-- Name: finish_minigame_session(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_minigame_session(p_session_id uuid, p_winner_id uuid, p_place integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_current_user uuid;
    v_group_id uuid;
    v_wager integer;
    v_status public.mini_game_status;
    v_participants uuid[];
    v_participant uuid;
    v_escrow integer;
BEGIN
    -- 1. Authentication gate.
    v_current_user := auth.uid();
    IF v_current_user IS NULL THEN
        RETURN jsonb_build_object('status', 'not_authenticated');
    END IF;

    -- 2. Session lookup + row lock: settlement and the status flip must be
    --    serialized against concurrent finishes/joins.
    SELECT group_id, shard_wager, status, participants
        INTO v_group_id, v_wager, v_status, v_participants
        FROM public.minigame_sessions
        WHERE id = p_session_id
        FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'session_not_found');
    END IF;

    -- 3. Access gate (direct-minigames 2026-08-27): group sessions may only
    --    be settled by active members; DIRECT sessions only by a
    --    participant (a bystander can never settle a wager they are not in).
    IF v_group_id IS NOT NULL THEN
        IF NOT public.is_group_member(v_group_id) THEN
            RETURN jsonb_build_object('status', 'not_member');
        END IF;
    ELSE
        IF v_current_user <> ALL(v_participants) THEN
            RETURN jsonb_build_object('status', 'not_allowed');
        END IF;
    END IF;

    -- 4. Lifecycle gate: only active sessions settle (repeat finishes are
    --    idempotent no-ops — the escrow must never be paid twice).
    IF v_status <> 'active' THEN
        RETURN jsonb_build_object('status', 'already_finished');
    END IF;

    -- 5. Winner gate: a declared winner must be one of the participants
    --    (GWAG: the winner is a player; NULL winner = draw).
    IF p_winner_id IS NOT NULL AND NOT (p_winner_id = ANY(v_participants)) THEN
        RETURN jsonb_build_object('status', 'invalid_winner');
    END IF;

    -- 6. Escrow settlement (GWAG §Wager Resolution).
    IF v_wager > 0 THEN
        IF p_winner_id IS NULL THEN
            -- Draw: refund every participant (minigame_refund reverses the
            -- minigame_wager deduction).
            FOREACH v_participant IN ARRAY v_participants
            LOOP
                UPDATE public.users
                SET personal_shards = personal_shards + v_wager
                WHERE id = v_participant;

                INSERT INTO public.shard_ledger
                    (user_id, delta, reason, reference_id)
                VALUES (v_participant, v_wager, 'minigame_refund',
                        p_session_id);
            END LOOP;
        ELSE
            -- Winner takes the whole pot; losers' deductions stand (their
            -- minigame_wager entry IS the loss record).
            v_escrow := v_wager * COALESCE(array_length(v_participants, 1), 0);

            UPDATE public.users
            SET personal_shards = personal_shards + v_escrow
            WHERE id = p_winner_id;

            INSERT INTO public.shard_ledger
                (user_id, delta, reason, reference_id)
            VALUES (p_winner_id, v_escrow, 'minigame_win', p_session_id);
        END IF;
    END IF;

    -- 7. Status flip + winner record (p_place is reserved for the future
    --    result-row contract; no minigame_results table exists yet).
    UPDATE public.minigame_sessions
    SET status = 'finished',
        winner_id = p_winner_id
    WHERE id = p_session_id;

    RETURN jsonb_build_object('status', 'finished');
END;
$$;


--

-- Name: join_minigame_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.join_minigame_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
    v_current_user uuid;
    v_group_id uuid;
    v_wager integer;
    v_status public.mini_game_status;
    v_participants uuid[];
    v_player_limit integer;
BEGIN
    -- 1. Authentication gate (same as create_minigame_session step 1).
    v_current_user := auth.uid();
    IF v_current_user IS NULL THEN
        RETURN jsonb_build_object('status', 'not_authenticated');
    END IF;

    -- 2. Session lookup + row lock: serializes concurrent joins so the
    --    participants append can never lose an update.
    SELECT group_id, shard_wager, status, participants, player_limit
        INTO v_group_id, v_wager, v_status, v_participants, v_player_limit
        FROM public.minigame_sessions
        WHERE id = p_session_id
        FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'session_not_found');
    END IF;

    -- 3. Access gate (direct-minigames 2026-08-27): group sessions keep the
    --    member-only join; DIRECT sessions admit the caller when they are a
    --    participant (idempotent re-join) or hold a PENDING invite (the
    --    direct play invite path) — is_group_member is recursion-safe.
    IF v_group_id IS NOT NULL THEN
        IF NOT public.is_group_member(v_group_id) THEN
            RETURN jsonb_build_object('status', 'not_member');
        END IF;
    ELSE
        IF v_current_user <> ALL(v_participants)
           AND NOT EXISTS (
               SELECT 1 FROM public.minigame_invites
               WHERE session_id = p_session_id
                 AND invitee_id = v_current_user
                 AND status = 'pending'
           )
        THEN
            RETURN jsonb_build_object('status', 'not_allowed');
        END IF;
    END IF;

    -- 4. Lifecycle gate: joins only on active sessions.
    IF v_status <> 'active' THEN
        RETURN jsonb_build_object('status', 'session_not_active');
    END IF;

    -- 5. Idempotency: an existing participant re-joining is a no-op
    --    (the client contract never removes participants).
    IF v_current_user = ANY(v_participants) THEN
        RETURN jsonb_build_object('status', 'joined');
    END IF;

    -- 5b. Player cap (direct-minigames 2026-08-27): a NEW participant is
    --     rejected once the frozen player_limit is reached (the cap was set
    --     at creation from the creator's subscription tier).
    IF array_length(v_participants, 1) >= v_player_limit THEN
        RETURN jsonb_build_object('status', 'player_limit_reached');
    END IF;

    -- 6. Escrow on join (GWAG: wagers deducted immediately for EACH
    --    participant; mirror of create_minigame_session steps 5 + 7).
    IF v_wager > 0 THEN
        UPDATE public.users
        SET personal_shards = personal_shards - v_wager
        WHERE id = v_current_user AND personal_shards >= v_wager;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('status', 'insufficient_shards');
        END IF;

        INSERT INTO public.shard_ledger (user_id, delta, reason, reference_id)
        VALUES (v_current_user, -v_wager, 'minigame_wager', p_session_id);
    END IF;

    -- 7. Append the caller to the participants array (self only).
    UPDATE public.minigame_sessions
    SET participants = participants || ARRAY[v_current_user]
    WHERE id = p_session_id;

    RETURN jsonb_build_object('status', 'joined');
END;
$$;


